style.css:
@-moz-document domain("web.whatsapp.com") {
body, html {
    background: url('https://za.pinterest.com/pin/236298311694460242') no-repeat center center fixed !important;
    background-size: cover !important;
  }

  .app-wrapper {
    background-color: rgba(255, 240, 245, 0.8) !important; /* pink tint */
  }

  ._3Bc7H, ._1jJ70, ._3j8Pd, ._2Ts6i, ._3XKXx {
    background-color: rgba(255, 192, 203, 0.2) !important; /* chat backgrounds */
    backdrop-filter: blur(6px);
  }

  ._1Flk2, ._3Uu1_ {
    background-color: rgba(255, 182, 193, 0.4) !important; /* header and search */
  }

  ._1b0m2, ._3OtEr {
    color: #8B008B !important; /* deep pink text */
  }

  .message-in, .message-out {
    background-color: rgba(255, 228, 225, 0.8) !important;
    border-radius: 12px !important;
  }

  ._1boJx, ._2vY4u, ._3uIPm {
    background-image: url('https://i.imgur.com/sXQdMhj.png') !important; /* floral pattern */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: bottom right;
    opacity: 0.1;
    pointer-events: none;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #ffb6c1;
    border-radius: 10px;
  }

  ::-webkit-scrollbar-track {
    background: transparent;
  }
}
